-- ================================================================
-- 6. 自检（只读）
-- ================================================================
SELECT 'value_type' AS item, COUNT(*) AS cnt FROM `gw_value_type`
UNION ALL SELECT 'value_type_field', COUNT(*) FROM `gw_value_type_field`
UNION ALL SELECT 'tpl_definition', COUNT(*) FROM `gw_tpl_definition`
UNION ALL SELECT 'tpl_field', COUNT(*) FROM `gw_tpl_field`
UNION ALL SELECT 'config_struct', COUNT(*) FROM `gw_config_struct`;

-- 模板按类别统计
SELECT `kind`, COUNT(*) AS cnt FROM `gw_tpl_definition` GROUP BY `kind`;

-- 引用闭合检查：不应有任何孤儿引用（结果应为空）
SELECT 'field' AS src, `id`, `value_type_id` FROM `gw_value_type_field` WHERE `value_type_id` NOT IN (SELECT `id` FROM `gw_value_type`)
UNION ALL SELECT 'tpl_field', `id`, `value_type_id` FROM `gw_tpl_field` WHERE `value_type_id` NOT IN (SELECT `id` FROM `gw_value_type`);
